// Adapted from shadcn/ui (MIT). Retained content is a ROC extension.
"use client";
import * as React from "react";
import { Collapsible as Primitive } from "./primitive-collapsible";
import { cn } from "./utils";
import "./collapsible.css";
const State = React.createContext(false);
function Collapsible({
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  children,
  ...props
}: React.ComponentProps<typeof Primitive.Root>) {
  const [local, setLocal] = React.useState(defaultOpen);
  const open = controlled ?? local;
  return (
    <State.Provider value={open}>
      <Primitive.Root
        open={open}
        onOpenChange={(value) => {
          if (controlled === undefined) setLocal(value);
          onOpenChange?.(value);
        }}
        {...props}
      >
        {children}
      </Primitive.Root>
    </State.Provider>
  );
}
const CollapsibleTrigger = Primitive.Trigger;
function CollapsibleContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Primitive.Content>) {
  const open = React.useContext(State);
  return (
    <Primitive.Content
      {...props}
      forceMount
      className={cn("roc-ui roc-collapsible", className)}
      aria-hidden={!open}
      inert={!open}
      data-open={open}
    >
      <div className="roc-collapsible-inner">{children}</div>
    </Primitive.Content>
  );
}
export { Collapsible, CollapsibleTrigger, CollapsibleContent };

"use client";
// ROC primitive: a trigger and a region it shows or hides.
import * as React from "react";
import { Slot } from "./primitive-slot";
import { composeEventHandlers } from "./primitive-utils";
import { useControllableState } from "./use-controllable-state";

const Context = React.createContext<{
  open: boolean;
  disabled: boolean;
  toggle: () => void;
  contentId: string;
} | null>(null);
const useCollapsible = () => {
  const context = React.useContext(Context);
  if (!context) throw new Error("Collapsible parts must be inside Collapsible.Root");
  return context;
};

type RootProps = Omit<React.ComponentProps<"div">, "defaultValue"> & {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  disabled?: boolean;
  asChild?: boolean;
};

function Root({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  disabled = false,
  asChild,
  ...props
}: RootProps) {
  const [open, setOpen] = useControllableState(openProp, defaultOpen, onOpenChange);
  const contentId = React.useId();
  const Comp: React.ElementType = asChild ? Slot.Root : "div";
  return (
    <Context.Provider value={{ open, disabled, toggle: () => setOpen(!open), contentId }}>
      <Comp
        data-state={open ? "open" : "closed"}
        data-disabled={disabled ? "" : undefined}
        {...props}
      />
    </Context.Provider>
  );
}

function Trigger({
  asChild,
  onClick,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const { open, disabled, toggle, contentId } = useCollapsible();
  const Comp: React.ElementType = asChild ? Slot.Root : "button";
  return (
    <Comp
      type={asChild ? undefined : "button"}
      aria-controls={contentId}
      aria-expanded={open}
      data-state={open ? "open" : "closed"}
      data-disabled={disabled ? "" : undefined}
      disabled={disabled}
      {...props}
      onClick={composeEventHandlers(onClick, toggle)}
    />
  );
}

function Content({
  forceMount,
  asChild,
  children,
  ...props
}: React.ComponentProps<"div"> & { forceMount?: boolean; asChild?: boolean }) {
  const { open, disabled, contentId } = useCollapsible();
  const Comp: React.ElementType = asChild ? Slot.Root : "div";
  // Closed content is emptied and hidden unless the caller keeps it ("forceMount")
  // to animate or retain its state. The empty region keeps `aria-controls` valid.
  if (!open && !forceMount)
    return (
      <Comp
        data-state="closed"
        data-disabled={disabled ? "" : undefined}
        {...props}
        id={contentId}
        hidden
      />
    );
  return (
    <Comp
      data-state={open ? "open" : "closed"}
      data-disabled={disabled ? "" : undefined}
      {...props}
      id={contentId}
    >
      {children}
    </Comp>
  );
}

export const Collapsible = { Root, Trigger, Content };

"use client";
// ROC primitive: render the caller's single child with our props merged in (`asChild`).
import * as React from "react";
import { composeRefs } from "./primitive-utils";

type AnyProps = Record<string, any>;

function mergeProps(slotProps: AnyProps, childProps: AnyProps) {
  const merged: AnyProps = { ...childProps };
  for (const key in childProps) {
    const slotValue = slotProps[key];
    const childValue = childProps[key];
    if (/^on[A-Z]/.test(key)) {
      if (slotValue && childValue) {
        merged[key] = (...args: unknown[]) => {
          const result = childValue(...args);
          slotValue(...args);
          return result;
        };
      } else if (slotValue) merged[key] = slotValue;
    } else if (key === "style") {
      merged[key] = { ...slotValue, ...childValue };
    } else if (key === "className") {
      merged[key] = [slotValue, childValue].filter(Boolean).join(" ");
    }
  }
  return { ...slotProps, ...merged };
}

type SlotProps = React.HTMLAttributes<HTMLElement> & {
  children?: React.ReactNode;
  ref?: React.Ref<any>;
};

function Root({ children, ref, ...slotProps }: SlotProps) {
  if (!React.isValidElement(children)) {
    if (React.Children.count(children) > 1) throw new Error("Slot needs one child");
    return null;
  }
  const child = children as React.ReactElement<AnyProps>;
  return React.cloneElement(child, {
    ...mergeProps(slotProps, child.props),
    ref: ref ? composeRefs(ref, child.props.ref) : child.props.ref,
  });
}

export const Slot = { Root };

"use client";
// ROC primitive helpers. Small, dependency-free building blocks.
import * as React from "react";

/** Run the caller's handler first; run ours unless the caller prevented default. */
export function composeEventHandlers<E extends { defaultPrevented: boolean }>(
  original: ((event: E) => void) | undefined,
  ours: ((event: E) => void) | undefined,
) {
  return (event: E) => {
    original?.(event);
    if (!event.defaultPrevented) ours?.(event);
  };
}

type PossibleRef<T> = React.Ref<T> | undefined;

/** Merge refs, forwarding React 19 ref cleanups. */
export function composeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        cleanups.push(
          typeof cleanup === "function" ? cleanup : () => ref(null),
        );
      } else if (ref) {
        (ref as React.RefObject<T | null>).current = node;
        cleanups.push(() => {
          (ref as React.RefObject<T | null>).current = null;
        });
      }
    }
    return () => cleanups.forEach((cleanup) => cleanup());
  };
}

export function useComposedRefs<T>(...refs: PossibleRef<T>[]) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(composeRefs(...refs), refs);
}

export function usePrevious<T>(value: T) {
  const ref = React.useRef({ value, previous: value });
  return React.useMemo(() => {
    if (ref.current.value !== value) {
      ref.current.previous = ref.current.value;
      ref.current.value = value;
    }
    return ref.current.previous;
  }, [value]);
}

"use client";
import { useState } from "react";
/** An optional owner, not a mandatory store or application provider. */
export function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (next: T) => void] {
  const [local, setLocal] = useState(defaultValue),
    current = value === undefined ? local : value;
  return [
    current,
    (next) => {
      if (Object.is(current, next)) return;
      if (value === undefined) setLocal(next);
      onChange?.(next);
    },
  ];
}

@import "./ui-base.css";
.roc-collapsible {
  display: grid;
  grid-template-rows: 0fr;
  visibility: hidden;
  transition:
    grid-template-rows var(--roc-motion-fast) var(--roc-motion-ease),
    visibility var(--roc-motion-fast);
}
.roc-collapsible[data-open="true"] {
  grid-template-rows: 1fr;
  visibility: visible;
}
.roc-collapsible-inner {
  min-height: 0;
  overflow: hidden;
  opacity: 0;
  filter: blur(var(--roc-motion-blur));
  transition:
    opacity var(--roc-motion-fast) var(--roc-motion-ease),
    filter var(--roc-motion-fast) var(--roc-motion-ease);
}
.roc-collapsible[data-open="true"] > .roc-collapsible-inner {
  opacity: 1;
  filter: blur(0);
}
@media (prefers-reduced-motion: reduce) {
  .roc-collapsible,
  .roc-collapsible-inner {
    transition: none;
  }
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

